const items = $input.all();
const blocks = items.filter(i => i.json && i.json.id).map(i => i.json);
const homeScope = $('Auth Check').item.json.homeScope;
const apiKey = $('Extract Key').item.json.apiKey;

const groups = {};
for (const b of blocks) {
  if (!groups[b.category]) groups[b.category] = [];
  groups[b.category].push(b);
}

let index = '';
for (const [cat, catItems] of Object.entries(groups).sort()) {
  const sorted = catItems.sort((a, b) => a.title.localeCompare(b.title));
  index += `\n${cat} (${catItems.length})\n`;
  for (const item of sorted) {
    const id8 = String(item.id).slice(0, 8);
    const scope = item.scope && item.scope !== homeScope ? ` [${item.scope}]` : '';
    const title = item.title.length > 70 ? item.title.slice(0, 67) + '...' : item.title;
    index += `  ${id8} ${title}${scope}\n`;
  }
}

const now = new Date().toISOString().slice(0, 10);
const title = `topic-map-${homeScope}`;
const content = `Context Store Index | scope:${homeScope} | ${blocks.length} blocks | ${Object.keys(groups).length} categories | ${now}\n${index}`;

return [{ json: {
  indexTitle: title,
  indexCategory: 'index',
  indexContent: content,
  indexTags: ['index', 'topic-map', homeScope, 'auto-generated'],
  indexMetadata: {
    source: 'context-digest',
    generated_at: now,
    scope: homeScope,
    block_count: blocks.length,
    category_count: Object.keys(groups).length
  },
  apiKey: apiKey,
  blockCount: blocks.length,
  categoryCount: Object.keys(groups).length
} }];

