const ollamaResponse = $input.first().json;
const promptData = $('Build LLM Prompt').item.json;
const topicMap = (ollamaResponse.response || '').trim();

// Build the topic map block content with header
const content = 'topic|summary|block_count|block_ids\n' + topicMap;
const now = new Date().toISOString().slice(0, 10);

return [{ json: {
  storeCategory: 'index',
  storeTitle: 'topic-map',
  storeContent: content,
  storeTags: ['index', 'topic-map', 'auto-generated'],
  storeMetadata: {
    source: 'context-digest',
    generated_at: now,
    block_count: promptData.blockCount,
    category_count: promptData.categoryCount,
    model: ollamaResponse.model || 'unknown',
    eval_count: ollamaResponse.eval_count || 0
  },
  topicMapPreview: content.slice(0, 500),
  evalCount: ollamaResponse.eval_count || 0
} }];

const storeResult = $input.first().json;
const buildData = $('Build Compact Index').item.json;

return [{ json: {
  success: true,
  action: 'digest',
  scope: buildData.indexMetadata.scope,
  title: buildData.indexTitle,
  blockCount: buildData.blockCount,
  categoryCount: buildData.categoryCount,
  contentLength: buildData.indexContent.length
} }];

const items = $input.all();
const headers = items[0].json.headers || {};
const body = items[0].json.body || items[0].json;
const rawKey = headers['x-context-key'] || '';
const apiKey = rawKey.replace(/[^a-f0-9]/gi, '');
return [{ json: { apiKey, body } }];

const auth = $('Auth Lookup').item.json;
if (!auth.home_scope || auth.home_scope === '__UNAUTHORIZED__') {
  return [{ json: { valid: false, error: 'Unauthorized: invalid API key' } }];
}
const homeScope = auth.home_scope;
const allowedScopes = Array.isArray(auth.allowed_scopes) ? auth.allowed_scopes : [];
const readScopes = [homeScope, ...allowedScopes];

function esc(val) {
  if (val === null || val === undefined) return 'NULL';
  return "'" + String(val).replace(/'/g, "''") + "'";
}

const scopeFilter = `scope IN (${readScopes.map(s => esc(s)).join(', ')})`;
const sql = `SELECT id, title, category, tags, scope, updated_at FROM context_blocks WHERE ${scopeFilter} ORDER BY category, title`;

return [{ json: { valid: true, metaQuery: sql, homeScope } }];

